local URL="https://sirius.menu/gen2"local Rayfield=loadstring(game:HttpGet(URL))()local Window=Rayfield:CreateWindow({Name="Go Hub - 擴充中心",Subtitle="v1.0",Theme="Ember",Configuration={Enabled=false}})local Hub=Window:CreateTab({Name="🌐 腳本目錄"})local function clearGuis()pcall(function()for _,v in pairs(game:GetService("CoreGui"):GetChildren())do if v:IsA("ScreenGui")and(v:FindFirstChild("Background")or v:FindFirstChild("Main")or v:FindFirstChild("TopBar")or v.Name:match("UI")or v.Name:match("Menu"))then v:Destroy()end end for _,v in pairs(game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui"):GetChildren())do if v:IsA("ScreenGui")and not v:FindFirstChild("SpaceWandUI")then v:Destroy()end end end)end Hub:CreateButton({Name="消息控制 (Gen2 環境)",Callback=function()clearGuis()task.spawn(function()loadstring(game:HttpGet("https://githubusercontent.com"))()end)Window:Unload()end})Hub:CreateButton({Name="載入經典 Sirius 環境",Callback=function()clearGuis()task.spawn(function()loadstring(game:HttpGet("https://sirius.menu/sirius"))()end)Window:Unload()end})Window:Notify({Title="Go Hub",Content="擴充目錄已載入",Duration=3})
